'return lower(:APP_USER);'))
,p_compute_when=>':APP_USER_ID is not null and :APP_USER_FIRST_NAME is null'
,p_compute_when_text=>'PLSQL'
,p_compute_when_type=>'EXPRESSION'
,p_version_scn=>'46642687738988'
);
