,p_computation_sequence=>10
,p_computation_item=>'COMPLETE_TASK_STATUS_IDS'
,p_static_id=>'complete-task-status-ids'
,p_computation_point=>'ON_NEW_INSTANCE'
,p_computation_type=>'QUERY'
,p_computation_processed=>'REPLACE_EXISTING'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select '':''||listagg(id, '':'' on overflow truncate '''' without count)||'':''',
'  from sp_task_statuses',
' where indicates_complete_yn = ''Y'''))
,p_computation_comment=>'should never have enough task statuses to need the overflow, but in place to avoid error - just in case'
,p_version_scn=>'SH256:uUgRY1b9UeQiCS4ukUrYz_rcVD-sSWVomh7w2bzbqA8'
);
