wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(38593521173798791848)
,p_plug_name=>'My Favorite &NOMENCLATURE_PROJECTS.'
,p_static_id=>'my-favorite-nomenclature-projects'
,p_icon_css_classes=>' '
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--scrollBody'
,p_plug_template=>4075786578761660127
,p_plug_display_sequence=>61
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select p.ID,',
'       --',
'       -- project name',
'       --',
'       --decode(greatest(length(p.project),80),80,p.PROJECT,substr(p.project,1,80)||''...'') project,',
'       p.project,',
'       --',
'       -- project owner',
'       --',
'       nvl(decode(t.first_name,null,t.email,t.first_name||'' ''||t.last_name),''No Owner'') the_owner,',
'       p.owner_id,',
'       p.TARGET_COMPLETE,',
'       --',
'       -- percent complete',
'       --',
'       p.PCT_COMPLETE||''%'' status,',
'       ''fa-pie-chart-''||p.PCT_COMPLETE as icon,',
'       --',
'       -- priority',
'       --',
'       nvl((select ''P''||priority from sp_project_priorities pp where pp.id = p.priority_id),''Not Prioritized'') priority,',
'       --',
'       -- Target',
'       --',
'       case when p.release_id is not null',
'            then (select t.release_train||'' ''||t.release from SP_RELEASE_TRAINS t where t.id = p.release_id)',
'            when p.target_complete is not null',
'            then to_char(p.target_complete,''Mon YYYY'')',
'            else ''No Target''',
'            end target,',
'       case when p.target_complete < sysdate',
'            then ''danger''',
'            when p.target_complete is null',
'            then ''warning''',
'            when p.PCT_COMPLETE >= 90',
'            then ''success'' ',
'            else ''info'' end target_badge_class,',
'       --',
'       -- Project favorites',
'       --',
'       ''Yes'' favorite,',
'       ''fa-heart u-danger-text'' favorite_icon,',
'       --',
'       -- project fields',
'       --',
'       lower(p.TAGS) tags,',
'       p.CREATED,',
'       apex_util.get_since(p.UPDATED) updated_since,',
'       p.updated,',
'       p.PROJECT_SIZE,',
'       p.project_url_name,',
'       p.friendly_identifier friendly_identifier1,',
'       --',
'       -- activity',
'       --',
'       (select ''<span class="fa fa-badge-check" aria-hidden="true" title="Active Activity"></span> '' from dual where exists (',
'           select 1 ',
'           from SP_ACTIVITIES ap ',
'           where (nvl(ap.private_yn,''N'') = ''N'' or ap.team_member_id = :APP_USER_ID)',
'             and ap.project_id = p.id and trunc(sysdate) between trunc(ap.start_date) and trunc(ap.end_date))) active_activity_icon',
'  from SP_PROJECTS p, ',
'       SP_INITIATIVES i,',
'       sp_team_members t,',
'       sp_favorites f',
'where ',
'      p.initiative_id = i.id and',
'      p.DUPLICATE_OF_PROJECT_ID is null and',
'      p.archived_yn = ''N'' and',
'      p.owner_id = t.id and',
'      f.project_id = p.id and ',
'      f.team_member_id = :APP_USER_ID and',
'      --',
'      p.PCT_COMPLETE < 100'))
,p_query_order_by_type=>'STATIC'
,p_query_order_by=>'updated desc'
,p_template_component_type=>'REPORT'
,p_lazy_loading=>false
,p_plug_source_type=>'TMPL_THEME_42$CONTENT_ROW'
,p_plug_query_num_rows=>5
,p_plug_query_num_rows_type=>'SET'
,p_plug_query_no_data_found=>'You have no &NOMENCLATURE_PROJECT. Associations.'
,p_show_total_row_count=>false
,p_plug_required_role=>wwv_flow_imp.id(176220694531802839665)
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>'instr(:HOME_PAGE_DISPLAY,'':FAV:'') > 0'
,p_plug_display_when_cond2=>'PLSQL'
,p_landmark_type=>'region'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'APPLY_THEME_COLORS', 'N',
  'AVATAR_DESCRIPTION', '&STATUS. Complete',
  'AVATAR_ICON', '&ICON.',
  'AVATAR_SHAPE', 't-Avatar--noShape',
  'AVATAR_SIZE', 't-Avatar--sm',
  'AVATAR_TYPE', 'icon',
  'BADGE_COL_WIDTH', 't-ContentRow-badge--md',
  'BADGE_LABEL', 'Target',
  'BADGE_LABEL_DISPLAY', 'N',
  'BADGE_STATE', 'TARGET_BADGE_CLASS',
  'BADGE_VALUE', 'TARGET',
  'DESCRIPTION', wwv_flow_string.join(wwv_flow_t_varchar2(
    '&ACTIVE_ACTIVITY_ICON!RAW. &PRIORITY. - &STATUS. - &PROJECT_SIZE.  ',
    '')),
  'DISPLAY_AVATAR', 'Y',
  'DISPLAY_BADGE', 'Y',
