,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select r.ID relation_id,',
'       p.project related_project,',
'       p.pct_complete,',
'       r.project_relation,',
'       r.CREATED,',
'       p.FRIENDLY_IDENTIFIER,',
