wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(23025237001046424118)
,p_event_id=>wwv_flow_imp.id(23025236773428424115)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_static_id=>'native-execute-plsql-code'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'items_to_return', 'P66_CURRENT_ID,P66_CURRENT_NAME,P66_N1_ID,P66_N1_NAME,P66_P1_ID,P66_P1_NAME,P66_P2_ID,P66_P2_NAME,P66_P3_ID,P66_P3_NAME,P66_INITIATIVE_ID',
  'items_to_submit', 'P66_RELEASE',
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    ':P66_CURRENT_ID   := null;',
    ':P66_CURRENT_NAME := null;',
    '',
    ':P66_N1_ID   := null;',
    ':P66_N1_NAME := null;',
    '',
    ':P66_P1_ID   := null;',
    ':P66_P1_NAME := null;',
    ':P66_P2_ID   := null;',
    ':P66_P2_NAME := null;',
    ':P66_P3_ID   := null;',
    ':P66_P3_NAME := null;',
    '',
    ':P66_INITIATIVE_ID := null;',
    '',
    'for c1 in (',
    '    select id, release, release_target_date, release_open_date',
    '      from sp_release_trains',
    '     where release_type = ''FULL''',
    '       and release_train = :P66_RELEASE',
    '       and release_open_completed = ''Y''',
    '       and release_completed = ''N''',
    '    union all                       -- added to catch no currently open',
    '    select null, null, null, null',
    '      from dual',
    '     order by release_target_date nulls last, release_open_date nulls last',
    ') loop',
    '    :P66_CURRENT_ID := c1.id;',
    '    :P66_CURRENT_NAME := c1.release;',
    '',
    '    for c2 in (',
    '        select id, release',
    '          from sp_release_trains',
    '         where release_type = ''FULL''',
    '           and release_train = :P66_RELEASE',
    '           and release_completed = ''N''',
    '           and (id != c1.id or c1.id is null)',
    '           and nvl(c1.release_target_date,trunc(sysdate)) <= release_target_date',
    '         order by release_target_date nulls last, release_open_date nulls last',
    '    ) loop',
    '        :P66_N1_ID := c2.id;',
    '        :P66_N1_NAME := c2.release;',
    '        exit;',
    '    end loop;',
    '',
    '    for c2 in (',
    '        select rownum, id, release',
    '          from (',
    '          select id, release',
    '            from sp_release_trains',
    '           where release_type = ''FULL''',
    '             and release_train = :P66_RELEASE',
    '             and release_open_completed = ''Y''',
    '             and release_completed = ''Y''',
    '             and (id != c1.id or c1.id is null)',
    '           order by release_target_date desc',
    '          )',
    '    ) loop',
    '        if c2.rownum = 1 then',
    '            :P66_P1_ID := c2.id;',
    '            :P66_P1_NAME := c2.release;',
    '        elsif c2.rownum = 2 then',
    '            :P66_P2_ID := c2.id;',
    '            :P66_P2_NAME := c2.release;',
    '        elsif c2.rownum = 3 then',
    '            :P66_P3_ID := c2.id;',
    '            :P66_P3_NAME := c2.release;',
    '        else exit;',
    '        end if;',
    '    end loop;',
    '',
    '    exit;',
    'end loop;')),
  'show_processing', 'N',
  'suppress_change_event', 'N')).to_clob
,p_wait_for_result=>'Y'
);
