wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(32733527806522472638)
,p_name=>'Out of Office Details (next 2 weeks)'
,p_static_id=>'out-of-office-details-next-2-weeks'
,p_template=>4075786578761660127
,p_display_sequence=>100
,p_region_template_options=>'#DEFAULT#:t-Region--noUI:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select t.event_type, ',
'       e.event_date, e.event_name,',
'       case when s.recur_freq is not null',
'            then ''Repeats ''||decode(s.recur_freq, ''D'', ''Daily'', ''WD'', ''Weekdays'', ''W'', ''Weekly'', ',
'                                            ''2W'', ''Every 2 Weeks'', ''M'', ''Montly'', s.recur_freq)||'', ''||',
'            case when to_char(s.start_date,''MONYYYY'') = to_char(s.end_date,''MONYYYY'') ',
'                 then to_char(s.start_date,''Mon fmDD'')||''-''||to_char(s.end_date,''fmDD'')',
'                    when to_char(s.start_date,''YYYY'') = to_char(s.end_date,''YYYY'') ',
'                 then to_char(s.start_date,''Mon fmDD'')||'' until ''||to_char(s.end_date,''Mon fmDD'')',
'                    else to_char(s.start_date,''Mon fmDD YYYY'')||'' until ''||to_char(s.end_date,''Mon fmDD YYYY'')',
'                    end',
'            end recur_frequency',
'  from sp_events e,',
'       sp_event_types t,',
'       sp_event_series s',
' where e.event_type_id = t.id',
'   and e.series_id = s.id (+)',
'   and (e.for_user_id = :P73_TEAM_MEMBER_ID or (e.for_user_id is null and t.general_event_yn = ''Y''))',
'   and e.event_date >= to_date(:APP_SYSDATE,''DD-MON-YYYY'')',
'   and e.event_date <= to_date(:APP_SYSDATE,''DD-MON-YYYY'') +14',
'  order by event_date'))
,p_display_when_condition=>'P73_TEAM_MEMBER_ID'
,p_display_condition_type=>'ITEM_IS_NOT_NULL'
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2542081983073888486
,p_query_num_rows=>150
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'No out of office in the next two weeks'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_required_patch=>wwv_flow_imp.id(31743638170417552010)
);
