 p_id=>wwv_flow_imp.id(23878768813687856394)
,p_chart_id=>wwv_flow_imp.id(23878767222888856386)
,p_static_id=>'data'
,p_seq=>10
,p_name=>'data'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select nvl(f.focus_area,''None Assigned'') series,',
'       t.release|| case when t.id = :P75_CURRENT_ID ',
'                        then '' *''',
'                        end label,',
'       count(*) value',
'  from sp_projects p,',
'       sp_release_trains t,',
'       sp_initiative_focus_areas f',
' where t.release_train = :P75_RELEASE',
'   and p.release_id = t.id',
'   and nvl(p.archived_yn,''N'') = ''N''',
'   and p.duplicate_of_project_id is null',
'   and p.focus_area_id = f.id (+)',
'   and t.release_type = ''FULL''',
'   and t.id in (:P75_CURRENT_ID,:P75_N1_ID,:P75_P1_ID,:P75_P2_ID,:P75_P3_ID)',
'   and p.initiative_id = nvl(:P75_INITIATIVE_ID,p.initiative_id)',
'group by t.id, t.release, f.focus_area',
'order by t.release, f.focus_area nulls last'))
,p_ajax_items_to_submit=>'P75_RELEASE,P75_INITIATIVE_ID'
,p_series_type=>'bar'
,p_series_name_column_name=>'SERIES'
,p_items_value_column_name=>'VALUE'
