 p_id=>wwv_flow_imp.id(46931619812020928556)
,p_name=>'Pivot Table'
,p_static_id=>'classic'
,p_template=>4075786578761660127
,p_display_sequence=>50
,p_include_in_reg_disp_sel_yn=>'Y'
,p_region_sub_css_classes=>'hide-report-total'
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select f.focus_area ob,',
'       f.focus_area,',
'       (select count(*)',
'          from sp_projects',
'         where nvl(archived_yn,''N'') = ''N''',
'           and duplicate_of_project_id is null',
'           and release_id = :P75_P3_ID',
'           and focus_area_id = f.id',
'           and initiative_id = nvl(:P75_INITIATIVE_ID,initiative_id)) p3_cnt,',
'       (select count(*)',
'          from sp_projects',
'         where nvl(archived_yn,''N'') = ''N''',
'           and duplicate_of_project_id is null',
'           and release_id = :P75_P2_ID',
'           and focus_area_id = f.id',
'           and initiative_id = nvl(:P75_INITIATIVE_ID,initiative_id)) p2_cnt,',
'       (select count(*)',
'          from sp_projects',
'         where nvl(archived_yn,''N'') = ''N''',
'           and duplicate_of_project_id is null',
'           and release_id = :P75_P1_ID',
'           and focus_area_id = f.id',
'           and initiative_id = nvl(:P75_INITIATIVE_ID,initiative_id)) p1_cnt,',
'       (select count(*)',
'          from sp_projects',
'         where nvl(archived_yn,''N'') = ''N''',
'           and duplicate_of_project_id is null',
'           and release_id = :P75_CURRENT_ID',
'           and focus_area_id = f.id',
'           and initiative_id = nvl(:P75_INITIATIVE_ID,initiative_id)) current_cnt,',
'       (select count(*)',
'          from sp_projects',
'         where nvl(archived_yn,''N'') = ''N''',
'           and duplicate_of_project_id is null',
'           and release_id = :P75_N1_ID',
'           and focus_area_id = f.id',
'           and initiative_id = nvl(:P75_INITIATIVE_ID,initiative_id)) next_cnt',
'  from sp_initiative_focus_areas f',
' where f.id in (select focus_area_id ',
'                  from sp_projects',
'                 where nvl(archived_yn,''N'') = ''N''',
'                   and duplicate_of_project_id is null',
'                   and release_id in (:P75_CURRENT_ID, :P75_N1_ID, :P75_P1_ID, :P75_P2_ID, :P75_P3_ID)',
'                   and initiative_id = nvl(:P75_INITIATIVE_ID,initiative_id))',
'union all',
'select null ob,',
'       ''None Assigned'' focus_area,',
'       (select count(*)',
'          from sp_projects',
'         where nvl(archived_yn,''N'') = ''N''',
'           and duplicate_of_project_id is null',
'           and release_id = :P75_P3_ID',
'           and focus_area_id is null',
'           and initiative_id = nvl(:P75_INITIATIVE_ID,initiative_id)) p3_cnt,',
'       (select count(*)',
'          from sp_projects',
'         where nvl(archived_yn,''N'') = ''N''',
'           and duplicate_of_project_id is null',
'           and release_id = :P75_P2_ID',
'           and focus_area_id is null',
'           and initiative_id = nvl(:P75_INITIATIVE_ID,initiative_id)) p2_cnt,',
'       (select count(*)',
'          from sp_projects',
'         where nvl(archived_yn,''N'') = ''N''',
'           and duplicate_of_project_id is null',
'           and release_id = :P75_P1_ID',
'           and focus_area_id is null',
'           and initiative_id = nvl(:P75_INITIATIVE_ID,initiative_id)) p1_cnt,',
'       (select count(*)',
'          from sp_projects',
'         where nvl(archived_yn,''N'') = ''N''',
'           and duplicate_of_project_id is null',
'           and release_id = :P75_CURRENT_ID',
'           and focus_area_id is null',
'           and initiative_id = nvl(:P75_INITIATIVE_ID,initiative_id)) current_cnt,',
'       (select count(*)',
'          from sp_projects',
'         where nvl(archived_yn,''N'') = ''N''',
'           and duplicate_of_project_id is null',
'           and release_id = :P75_N1_ID',
'           and focus_area_id is null',
'           and initiative_id = nvl(:P75_INITIATIVE_ID,initiative_id)) next_cnt',
'  from dual'))
,p_footer=>'* indicates the current Release'
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P75_INITIATIVE_ID'
,p_lazy_loading=>false
