,p_static_id=>'when-select-release'
,p_event_sequence=>10
,p_triggering_element_type=>'ITEM'
,p_triggering_element=>'P75_RELEASE'
,p_condition_element=>'P75_RELEASE'
,p_triggering_condition_type=>'NOT_NULL'
,p_bind_type=>'bind'
,p_execution_type=>'IMMEDIATE'
,p_bind_event_type=>'change'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(23878785889040856456)
,p_event_id=>wwv_flow_imp.id(23878784485987856453)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_static_id=>'native-execute-plsql-code'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'items_to_return', 'P75_CURRENT_ID,P75_CURRENT_NAME,P75_N1_ID,P75_N1_NAME,P75_P1_ID,P75_P1_NAME,P75_P2_ID,P75_P2_NAME,P75_P3_ID,P75_P3_NAME,P75_INITIATIVE_ID',
  'items_to_submit', 'P75_RELEASE',
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    ':P75_CURRENT_ID   := null;',
    ':P75_CURRENT_NAME := null;',
    '',
    ':P75_N1_ID   := null;',
    ':P75_N1_NAME := null;',
    '',
    ':P75_P1_ID   := null;',
    ':P75_P1_NAME := null;',
    ':P75_P2_ID   := null;',
    ':P75_P2_NAME := null;',
    ':P75_P3_ID   := null;',
    ':P75_P3_NAME := null;',
    '',
    ':P75_INITIATIVE_ID := null;',
    '',
    'for c1 in (',
    '    select id, release, release_target_date, release_open_date',
    '      from sp_release_trains',
    '     where release_type = ''FULL''',
    '       and release_train = :P75_RELEASE',
    '       and release_open_completed = ''Y''',
    '       and release_completed = ''N''',
    '    union all                       -- added to catch no currently open',
    '    select null, null, null, null',
    '      from dual',
    '     order by release_target_date nulls last, release_open_date nulls last',
    ') loop',
    '    :P75_CURRENT_ID := c1.id;',
    '    :P75_CURRENT_NAME := c1.release;',
    '',
    '    for c2 in (',
    '        select id, release',
    '          from sp_release_trains',
    '         where release_type = ''FULL''',
    '           and release_train = :P75_RELEASE',
    '           and release_completed = ''N''',
    '           and (id != c1.id or c1.id is null)',
    '           and nvl(c1.release_target_date,trunc(sysdate)) <= release_target_date',
    '         order by release_target_date nulls last, release_open_date nulls last',
    '    ) loop',
    '        :P75_N1_ID := c2.id;',
    '        :P75_N1_NAME := c2.release;',
    '        exit;',
    '    end loop;',
    '',
    '    for c2 in (',
    '        select rownum, id, release',
    '          from (',
    '          select id, release',
    '            from sp_release_trains',
    '           where release_type = ''FULL''',
    '             and release_train = :P75_RELEASE',
    '             and release_open_completed = ''Y''',
    '             and release_completed = ''Y''',
    '             and (id != c1.id or c1.id is null)',
    '           order by release_target_date desc',
    '          )',
    '    ) loop',
    '        if c2.rownum = 1 then',
    '            :P75_P1_ID := c2.id;',
    '            :P75_P1_NAME := c2.release;',
    '        elsif c2.rownum = 2 then',
    '            :P75_P2_ID := c2.id;',
    '            :P75_P2_NAME := c2.release;',
