,p_plug_name=>'Groups'
,p_static_id=>'groups'
,p_region_template_options=>'#DEFAULT#'
,p_escape_on_http_output=>'N'
,p_plug_template=>2103954283454391425
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select g.ID,',
'       g.GROUP_NAME,',
'       g.DESCRIPTION,',
'       g.group_tag,',
'       --',
'       -- tracking columns',
'       --',
'       g.CREATED,',
'       g.CREATED_BY,',
'       g.UPDATED,',
'       g.UPDATED_BY,',
'       --',
'       -- members',
'       --',
'       (select count(*) ',
'       from SP_GROUP_MEMBERS gm, ',
'            SP_TEAM_MEMBERS tm ',
'       where tm.id = gm.TEAM_MEMBER_ID and ',
'             gm.group_id = g.id and ',
'             nvl(tm.IS_CURRENT_YN,''Y'') = ''Y'') group_members,',
'       --',
'       -- full time',
'       --',
'       (select count(*) ',
'        from SP_GROUP_MEMBERS gm, ',
'             SP_TEAM_MEMBERS tm ',
'        where tm.id = TEAM_MEMBER_ID and ',
'              gm.group_id = g.id and ',
'              gm.full_time_yn = ''Y'' and ',
'              tm.IS_CURRENT_YN = ''Y'') full_time,',
'       --',
'       -- laeders',
'       --',
'       (select count(*) ',
'        from SP_GROUP_MEMBERS gm, ',
'             SP_TEAM_MEMBERS tm ',
'        where tm.id = TEAM_MEMBER_ID and ',
'              gm.group_id = g.id and ',
'              gm.group_leader_yn = ''Y'' and ',
'              tm.IS_CURRENT_YN = ''Y'') group_Leaders',
'  from SP_GROUPS g'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_prn_page_header=>'Groups'
,p_ai_enabled=>false
);
