    'var lRel; ',
    '',
    'lRel = $v(''P135_DROP_RELEASE'');',
    '',
    'if (lRel) {',
    '',
    '  $(''#''+$v(''P135_DRAG_ITEM_ID'')+''-release'').text(lRel);',
