wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(128506031044965606674)
,p_name=>'do not drop - Search Results'
,p_static_id=>'do-not-drop-search-results'
,p_region_name=>'search-results'
,p_template=>4075786578761660127
,p_display_sequence=>40
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'     select ',
'           case ',
'             when pct_complete between 10 and 20 then 1',
'             when pct_complete = 30 then 2',
'             when pct_complete = 40 then 3',
'             when pct_complete between 50 and 70 then 4',
'             when pct_complete between 80 and 100 then 5',
'           end column_id,',
'           sp.id,',
'           sp.project,',
'',
'           case when sp.release_id is not null then re.release_train||'' ''||re.release',
'                else ''NA'' end release,',
'',
'           sp.release_id,',
'           sp.tags,',
'           pp.priority,',
'           ps.project_size,',
'           ps.effort_days,',
'           sp.pct_complete,',
'           nvl(fa.focus_area,''Unallocated'') focus_area,',
'           sp.status_scale,',
'           (select tm.first_name||'' ''||tm.last_name from sp_team_members tm where sp.owner_id = tm.id) name',
'      from sp_projects sp',
'      inner join sp_project_priorities pp on sp.priority_id = pp.id',
'      inner join sp_project_sizes ps on sp.project_size = ps.project_size ',
'      left outer join sp_initiative_focus_areas fa on sp.focus_area_id = fa.id',
'      left outer join sp_release_trains re on sp.release_id = re.id',
'      where sp.pct_complete > 0 ',
'        and sp.initiative_id = :P158_INITIATIVE_ID',
'        and sp.archived_yn = ''N'' ',
'        and sp.duplicate_of_project_id is null',
'        --and sp.status_scale = ''A''',
'        and ((sp.release_id is null and sp.pct_complete < 100)',
'      --    or (sp.release_id is not null and (re.release_completed = ''N'' or re.id is null)))',
'            or (sp.release_id is not null and (sysdate < release_target_date or re.id is null)))',
'        or sp.id is null'))
,p_display_condition_type=>'NEVER'
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2542081983073888486
,p_query_num_rows=>100
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
