wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(128235716035804329976)
,p_name=>'Kanban Board'
,p_static_id=>'kanban-board'
,p_template=>3374665444246510938
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'  x.focus_area_name focus_area,',
'  y.id,',
'  y.project project,',
'  x.column_id,',
'  y.priority,',
'  case y.priority',
'  when 1 then ''kb-Card--p1''',
'  when 2 then ''kb-Card--p2''',
'  when 3 then ''kb-Card--p3''',
'  when 4 then ''kb-Card--p4''',
'  when 5 then ''kb-Card--p5''',
'  else null end p_style,',
'  y.kb_stack_rank,',
'  y.project_size,',
'  y.effort_days,',
'  y.weight,',
'  y.pct_complete,',
'  decode(y.release,''NA'',''N'',''Y'') release_dependent_yn,',
'  y.status_scale,',
'  x.focus_area_id,',
'  y.release,',
'  nvl(y.name,''(No Owner)'') name,',
'  nvl2(y.id,null,''kb-Blank'') display,',
'  row_number() over(PARTITION BY x.focus_area_id ORDER BY x.focus_area,x.column_id,y.kb_stack_rank,y.id) row_split,',
'  row_number() over(PARTITION BY x.focus_area_id,x.column_id ORDER BY x.focus_area,x.column_id,y.kb_stack_rank,y.id) column_split,',
'  ''apex.navigation.redirect(''''''||',
'  apex_util.prepare_url(p_url => ''f?p='' || :APP_ID || '':36:'' || :APP_SESSION || ''::NO::P36_ID:'' || y.id)||'''''')'' as link,',
'  -- Display Attributes',
'  null attrs,',
'  case',
'  (select count(*) from APEX_APPL_ACL_USER_ROLES where role_static_id in (''CONTRIBUTOR'', ''ADMINISTRATOR'') and application_id = :app_id and user_name = :app_user)',
'    when 0 then null',
'    else ''kb-Sortable'' end sortable',
'from ',
'------------------------------------------------',
'-- Inline view that lays out the Kanban Board --',
'------------------------------------------------',
'(select * from',
'      -------------',
'      -- Columns --',
'      -------------',
'      (select ',
'         column_value column_id',
'       FROM TABLE(apex_string.split(nvl(:p158_kb_column_id,''1:2:3:4:5''),'':''))) columns',
'       cross join',
'      ------------',
'      -- Groups --',
'      ------------',
'      (select ',
'        focus_area||(select '' (''||stm.first_name||'' ''||stm.last_name||'')'' from SP_TEAM_MEMBERS stm where stm.id = fa.development_owner_id) focus_area_name,',
'        focus_area,',
'        to_char(id) focus_area_id',
'      from',
'        sp_initiative_focus_areas fa',
'      where fa.initiative_id = :P158_INITIATIVE_ID',
'        and active_yn = ''Y''',
'      --------------------------------------------------',
'      -- Create a sudo group for unallocated projects --',
'      -------------------------------------------------- ',
'      union all select ''Unallocated'', ''Unallocated'', ''Unallocated'' from dual) groups) x',
'  --------------------------------------------------------',
'  -- An inline view of all the projects is outer joined --',
'  -- to the Kanban Board                                --',
'  --------------------------------------------------------',
'  left join (',
'      select ',
'           case ',
'             when pct_complete between 10 and 20 then 1',
'             when pct_complete = 30 then 2',
'             when pct_complete = 40 then 3',
'             when pct_complete between 50 and 70 then 4',
'             when pct_complete between 80 and 100 then 5',
'           end column_id,',
'           case ',
'              when sp.release_id is not null then re.release_train||'' ''||re.release',
'              else ''NA'' end release,',
'           to_char(sp.id) as id,',
'           sp.project,',
'           sp.tags,',
'           sp.kb_stack_rank,',
'           pp.priority,',
'           ps.project_size,',
'           ps.effort_days,',
'           pp.priority * ps.effort_days weight,',
'           sp.pct_complete,',
'           sp.status_scale,',
'           nvl(to_char(sp.focus_area_id),''Unallocated'') focus_area_id,',
'           (select tm.first_name||'' ''||tm.last_name from sp_team_members tm where sp.owner_id = tm.id) name',
'      from sp_projects sp',
'      inner join sp_project_priorities pp on sp.priority_id = pp.id',
'      inner join sp_project_sizes ps on sp.project_size = ps.project_size ',
'      left outer join sp_release_trains re on sp.release_id = re.id',
'      ----------------------------------------',
'      -- Predicates to filter projects only --',
'      ----------------------------------------',
'      where sp.pct_complete > 0 ',
'        and sp.archived_yn = ''N'' ',
'        and sp.duplicate_of_project_id is null',
'        and sp.initiative_id = :P158_INITIATIVE_ID',
'        --and sp.status_scale = ''A''',
'        and (pp.priority in (select column_value from table(apex_string.split(:p158_kb_priority,'':''))) or :p158_kb_priority is null)',
'        and (sp.project_size in (select column_value from table(apex_string.split(:p158_kb_project_size,'':'')))  or :p158_kb_project_size is null)',
'        and ((select count(*) from table(apex_string.split(sp.tags,'','')) t1 inner join table(apex_string.split(:P158_KB_TAGS,'':'')) t2 on t1.column_value = t2.column_value) > 0  or :p158_kb_tags is null)',
'        and ((sp.release_id is null and sp.pct_complete < 100)',
'              or (sp.release_id is not null and (sysdate < release_target_date or re.id is null)))',
'        or sp.id is null',
'  ) y on x.focus_area_id = y.focus_area_id ',
'     and x.column_id = y.column_id',
'     and (y.release in (select column_value from table(apex_string.split(:p158_kb_release,'':''))) or :p158_kb_release is null)',
'     and (y.pct_complete in (select column_value from table(apex_string.split(:p158_kb_pct_complete,'':''))) or :p158_kb_pct_complete is null)',
'     and (nvl(y.name,''$$NULL$$'') in (select column_value from table(apex_string.split(:p158_kb_name,'':''))) or :p158_kb_name is null)',
'     and (instr(upper(y.project||y.name||x.focus_area||y.tags||y.project_size), upper(:P158_KB_SEARCH), 1,1) > 0 or :P158_KB_SEARCH is null)',
'----------------------------------------------------',
'-- Predicates that filter both board and projects --',
'----------------------------------------------------',
'where (x.focus_area in (select column_value from table(apex_string.split(:p158_kb_focus_area,'':''))) or :p158_kb_focus_area is null)',
'order by x.focus_area, x.column_id, kb_stack_rank, y.id'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P158_KB_PCT_COMPLETE,P158_KB_SEARCH,P158_KB_RELEASE,P158_KB_TAGS,P158_KB_NAME,P158_KB_PRIORITY,P158_KB_PROJECT_SIZE,P158_KB_FOCUS_AREA,P158_KB_COLUMN_ID,P158_KB_VIEWS'
,p_lazy_loading=>true
,p_query_row_template=>wwv_flow_imp.id(46431926092757091186)
,p_query_headings=>'return ''New:Architecting:Ready:In-Progress:Dev Done'';'
,p_query_headings_type=>'FUNCTION_BODY_RETURNING_COLON_DELIMITED_LIST'
,p_query_num_rows=>1000
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'SHOW_ALL'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
