wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(38297140193959916374)
,p_event_id=>wwv_flow_imp.id(38297139466184916373)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_static_id=>'native-execute-plsql-code'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'items_to_submit', 'P158_SR_ABOVE,P158_SR_BELOW,P158_DROP_FOCUS_AREA_ID,P158_DROP_COLUMN_ID,P158_DRAG_ITEM_ID,P158_DRAG_COLUMN_ID,P158_DRAG_FOCUS_AREA_ID',
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'declare',
    '',
    '  insufficient_data exception;',
    '  lv_stack_rank number;',
    '',
    'begin',
    '',
    'if :P158_DRAG_FOCUS_AREA_ID is null ',
    '  or :P158_DROP_FOCUS_AREA_ID is null ',
    '  or :P158_DRAG_ITEM_ID is null ',
    '  or :P158_DRAG_COLUMN_ID is null ',
    '  or :P158_DROP_COLUMN_ID is null ',
    '  or :P158_INITIATIVE_ID is null',
    '  or :P158_SR_ABOVE is null',
    '  or :P158_SR_BELOW is null then',
    '  raise insufficient_data;',
    'end if;',
    '',
    'if :P158_SR_ABOVE != ''None'' and :P158_SR_BELOW != ''None'' then',
    '',
    '  select sum(kb_stack_rank) / 2 into lv_stack_rank from sp_projects',
    '  where initiative_id = :P158_INITIATIVE_ID and id in (:P158_SR_ABOVE,:P158_SR_BELOW);',
    '',
    '  update sp_projects set kb_stack_rank = lv_stack_rank',
    '  where id = :P158_DRAG_ITEM_ID and initiative_id = :P158_INITIATIVE_ID;',
    '',
    'elsif :P158_SR_ABOVE = ''None'' and :P158_SR_BELOW != ''None'' then',
    '',
    '  select kb_stack_rank -1 into lv_stack_rank from sp_projects',
    '  where initiative_id = :P158_INITIATIVE_ID and id = :P158_SR_BELOW;',
    '',
    '  update sp_projects set kb_stack_rank = lv_stack_rank',
    '  where id = :P158_DRAG_ITEM_ID and initiative_id = :P158_INITIATIVE_ID;',
    '',
    'elsif :P158_SR_ABOVE != ''None'' and :P158_SR_BELOW = ''None'' then',
    '',
    '  select kb_stack_rank +1 into lv_stack_rank from sp_projects',
    '  where initiative_id = :P158_INITIATIVE_ID and id = :P158_SR_ABOVE;',
    '',
    '  update sp_projects set kb_stack_rank = lv_stack_rank ',
    '  where id = :P158_DRAG_ITEM_ID and initiative_id = :P158_INITIATIVE_ID;',
    '',
    'end if;',
    '',
    '',
    'if :P158_DRAG_FOCUS_AREA_ID != :P158_DROP_FOCUS_AREA_ID then',
    '  update sp_projects',
    '  set focus_area_id = decode(:P158_DROP_FOCUS_AREA_ID,''Unallocated'',null,:P158_DROP_FOCUS_AREA_ID)',
    '  where id = :P158_DRAG_ITEM_ID and initiative_id = :P158_INITIATIVE_ID;',
    'end if;',
    '',
    'if :P158_DRAG_COLUMN_ID != :P158_DROP_COLUMN_ID then',
    '  update sp_projects',
    '  set pct_complete = decode(:P158_DROP_COLUMN_ID,1,20,2,30,3,40,4,50,5,80)',
    '  where id = :P158_DRAG_ITEM_ID and initiative_id = :P158_INITIATIVE_ID;',
    'end if;',
    '',
    'exception',
    '',
    '  when insufficient_data then RAISE_APPLICATION_ERROR(-20001, ''Insufficient Data!'');  ',
    '  ',
    'end;')),
  'show_processing', 'N')).to_clob
,p_wait_for_result=>'Y'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(38297140799899916375)
,p_event_id=>wwv_flow_imp.id(38297139466184916373)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_static_id=>'native-javascript-code'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'var lPct; ',
    'var lCls;',
    '',
    'if ($v(''P158_DRAG_COLUMN_ID'') != $v(''P158_DROP_COLUMN_ID'')) {',
    '  switch ($v(''P158_DROP_COLUMN_ID'')) {',
    '    case "1":',
    '      lPct = "20%";',
    '      lCls = "t-Badge-icon fa fa-pie-chart-20";',
    '      break;',
    '    case "2":',
    '       lPct = "30%";',
    '      lCls = "t-Badge-icon fa fa-pie-chart-30";',
    '      break;',
    '    case "3":',
    '      lPct = "40%";',
    '      lCls = "t-Badge-icon fa fa-pie-chart-40";',
    '      break;',
    '    case "4":',
    '      lPct = "50%";',
    '      lCls = "t-Badge-icon fa fa-pie-chart-50";',
    '      break;',
    '    case "5":',
    '      lPct = "80%";',
    '      lCls = "t-Badge-icon fa fa-pie-chart-80";',
    '  }',
    '',
    '  $(''#''+$v(''P158_DRAG_ITEM_ID'')+''-pct-complete'').find(''.t-Badge-value'').text(lPct);',
    '  $(''#''+$v(''P158_DRAG_ITEM_ID'')+''-pct-complete'').find(''.t-Badge-icon'').attr(''Class'',lCls);',
    '',
    '  apex.message.showPageSuccess(''Project Move Success'');',
    '',
    '}',
    '',
    '')))).to_clob
,p_server_condition_type=>'NOT_DISPLAYING_INLINE_VALIDATION_ERRORS'
);
