,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select r.ID relation_id,',
'       ''This Task '' ||',
'           nvl((select relation_type from sp_relation_types',
'                 where id = r.relation_type_id),''relates to'') ||'' "''||',
'           p.task ||',
'           case when p.task is not null then '' ('' end ||',
'           (select task_type from sp_task_types rt where rt.id = p.task_type_id)||',
'            case when p.task_sub_type_id is not null ',
'                 then '': ''||(select task_type from sp_task_types rt where rt.id = p.task_sub_type_id) ',
'                 end ||',
'                 case when p.task is not null then '')'' end ||''"'' relation,',
'       r.relation_details,',
'       (select case when first_name is not null or last_name is not null',
'                    then first_name||'' ''||last_name',
'                    else email',
'                    end',
'               from sp_team_members t where t.id = p.owner_id) owner,',
'       p.target_complete,',
'       r.CREATED,',
'       lower(r.created_by) created_by,',
'       r.updated,',
'       lower(r.updated_by) updated_by',
'  from SP_TASK_RELATED r,',
'       sp_tasks p',
' where r.TASK_ID = :P502_TASK_ID',
'   and r.RELATED_TASK_ID = p.id',
'union',
'select r.ID relation_id,',
'       ''"''||rp.task ||',
'           case when rp.task is not null then '' ('' end ||',
'           (select task_type from sp_task_types rt where rt.id = rp.task_type_id)||',
'            case when rp.task_sub_type_id is not null ',
'                 then '': ''||(select task_type from sp_task_types rt where rt.id = rp.task_sub_type_id) ',
'                 end ||',
'                 case when rp.task is not null then '')'' end ||''" ''||',
'        nvl((select nvl(relation_reverse,relation_type) from sp_relation_types',
'              where id = r.relation_type_id),''relates to'') ||',
'       '' This Task'' relation,',
'       r.relation_details,',
'       (select case when first_name is not null or last_name is not null',
'                    then first_name||'' ''||last_name',
'                    else email',
'                    end',
'               from sp_team_members t where t.id = rp.owner_id) owner,',
'       rp.target_complete,',
'       r.CREATED,',
'       lower(r.created_by) created_by,',
'       r.updated,',
'       lower(r.updated_by) updated_by',
'  from SP_TASK_RELATED r,',
'       sp_tasks rp',
' where r.RELATED_TASK_ID = :P502_TASK_ID',
'   and r.task_id = rp.id'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P502_TASK_ID'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_plug_display_condition_type=>'EXISTS'
,p_plug_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1',
'  from sp_tasks t,',
'       sp_task_types tt',
' where t.project_id = :P502_PROJECT_ID',
'   and t.id != :P502_TASK_ID',
'   and nvl(t.task_sub_type_id,t.task_type_id) = tt.id ',
'   and tt.static_id not like ''MILESTONE%''',
'   and tt.static_id not like ''REVIEW%'''))
