wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(31842513680999726825)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load data for edit'
,p_static_id=>'load-data-for-edit'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for c1 in (',
'    select event_type_id,',
'           (select general_event_yn from sp_event_types',
'             where id = e.event_type_id) general_event_yn,',
'           event_date,',
'           event_name,',
'           event_details,',
'           for_user_id,',
'           series_id,',
'           created_by,',
'           apex_util.get_since(created) created_since,',
'           updated_by,',
'           apex_util.get_since(updated) updated_since',
'      from sp_events e',
'     where id = :P704_ID',
') loop',
'    :P704_EVENT_TYPE_ID    := c1.event_type_id;',
'    :P704_GENERAL_EVENT_YN := c1.general_event_yn;',
'    :P704_EVENT_DETAILS    := c1.event_details;',
'    :P704_EVENT_NAME       := c1.event_name;',
'    :P704_CREATED_BY       := c1.created_by;',
'    :P704_CREATED_SINCE    := c1.created_since;',
'    :P704_UPDATED_BY       := c1.updated_by;',
'    :P704_UPDATED_SINCE    := c1.updated_since;',
'',
'    if c1.for_user_id is null then',
'       :P704_EVENT_FOR := ''A'';',
'    elsif sp_util.get_user_id(c1.created_by) = c1.for_user_id then',
'        :P704_EVENT_FOR := ''M'';',
'    else   ',
'        :P704_EVENT_FOR := ''E'';    ',
'    end if;',
'',
'    if c1.for_user_id is not null then',
'        :P704_FOR_USER_ID := c1.for_user_id;',
'        :P704_PREVIOUS_FOR_USER_ID := c1.for_user_id;',
'    end if;',
'',
'    :P704_EVENT_DATE := c1.event_date;',
'',
'    if c1.series_id is not null then',
'        for c2 in (',
'            select recur_freq, start_date, end_date',
'              from sp_event_series',
'             where id = c1.series_id',
'        ) loop',
'            :P704_RECURS     := ''Y'';',
'            :P704_RECUR_FREQ := c2.recur_freq;',
'            :P704_START_DATE := c2.start_date;',
'            :P704_END_DATE   := c2.end_date;',
'            :P704_SERIES_ID  := c1.series_id;',
'        end loop;',
'    end if;',
'end loop;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'P704_ID'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_internal_uid=>31842513680999726825
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(35903689271131405423)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load Quick Picks'
,p_static_id=>'load-quick-picks'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   l_cnt  number := 1;',
'begin',
'',
'for c1 in (',
'    select event_type, id',
'      from sp_event_types',
'     where active_yn = ''Y''',
' --      and general_event_yn = ''N''',
'       and quick_pick_yn = ''Y''',
'      order by event_type desc',
') loop',
'    if l_cnt = 1 then',
'        :P704_QP1    := c1.event_type;',
'        :P704_QP1_ID := c1.id;',
'    elsif l_cnt = 2 then',
'        :P704_QP2    := c1.event_type;',
'        :P704_QP2_ID := c1.id;',
'    elsif l_cnt = 3 then',
'        :P704_QP3    := c1.event_type;',
'        :P704_QP3_ID := c1.id;',
'    elsif l_cnt = 4 then',
'        :P704_QP4    := c1.event_type;',
'        :P704_QP4_ID := c1.id;',
'    elsif l_cnt = 5 then',
'        :P704_QP5    := c1.event_type;',
'        :P704_QP5_ID := c1.id;',
'    end if;',
'',
'    l_cnt := l_cnt + 1;',
'end loop;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>35903689271131405423
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(33518813618354200426)
,p_process_sequence=>60
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'reload OOO Summary, if necessary'
,p_static_id=>'reload-ooo-summary-if-necessary'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_for_user_id  number;',
'    l_updated_yn   varchar2(1);',
'begin',
'',
'l_for_user_id := case :P704_EVENT_FOR when ''E'' ',
'                                      then :P704_FOR_USER_ID',
'                                      when ''M''',
'                                      then :APP_USER_ID',
'                                      end;',
'',
'if :P704_PREVIOUS_FOR_USER_ID != l_for_user_id then',
'    sp_event_util.load_one_ooo (',
'        p_team_member_id => :P704_PREVIOUS_FOR_USER_ID,',
'        p_updated_yn     => l_updated_yn );',
'end if;',
'',
'if l_for_user_id is not null then',
'    sp_event_util.load_one_ooo (',
'        p_team_member_id => l_for_user_id,',
'        p_updated_yn     => l_updated_yn );',
'end if;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>33518813618354200426
);
wwv_flow_imp_page.create_page_process(
