wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(35933891040384364379)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load Quick Picks'
,p_static_id=>'load-quick-picks'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   l_cnt  number := 1;',
'begin',
'',
'for c1 in (',
'    select event_type, id',
'      from sp_event_types',
'     where active_yn = ''Y''',
'       and general_event_yn = ''Y''',
'       and quick_pick_yn = ''Y''',
'      order by event_type desc',
') loop',
'    if l_cnt = 1 then',
'        :P709_QP1    := c1.event_type;',
'        :P709_QP1_ID := c1.id;',
'    elsif l_cnt = 2 then',
'        :P709_QP2    := c1.event_type;',
'        :P709_QP2_ID := c1.id;',
'    elsif l_cnt = 3 then',
'        :P709_QP3    := c1.event_type;',
'        :P709_QP3_ID := c1.id;',
'    elsif l_cnt = 4 then',
'        :P709_QP4    := c1.event_type;',
'        :P709_QP4_ID := c1.id;',
'    elsif l_cnt = 5 then',
'        :P709_QP5    := c1.event_type;',
'        :P709_QP5_ID := c1.id;',
'    end if;',
'',
'    l_cnt := l_cnt + 1;',
'end loop;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>35933891040384364379
);
end;
