'       u.user_name_lc USERNAME,',
'       u.role_names ACCESS_ROLE, ',
'       case when t.id is not null then ''Yes'' else ''No'' end is_team_member,',
'       t.id team_member_id',
'  from APEX_APPL_ACL_USERS u,',
'       t',
' where u.APPLICATION_ID = :APP_ID',
