begin
wwv_flow_imp_page.create_page(
 p_id=>10790
,p_name=>'Team Member Notifications'
,p_alias=>'TEAM-MEMBER-NOTIFICATIONS'
,p_step_title=>'Team Member Notifications'
,p_autocomplete_on_off=>'OFF'
,p_step_template=>4075783602716660119
,p_page_css_classes=>'rw-pillar--sienna'
,p_page_template_options=>'#DEFAULT#'
,p_required_role=>wwv_flow_imp.id(176220694375517839665)
,p_protection_level=>'C'
,p_page_component_map=>'18'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(18062403425221832044)
,p_plug_name=>'Breadcrumb'
,p_static_id=>'breadcrumb'
,p_region_template_options=>'#DEFAULT#:t-BreadcrumbRegion--useBreadcrumbTitle'
,p_component_template_options=>'#DEFAULT#'
,p_escape_on_http_output=>'N'
,p_plug_template=>2534890969069732905
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_01'
,p_plug_item_display_point=>'ABOVE'
,p_menu_id=>wwv_flow_imp.id(176220395320510839347)
,p_plug_source_type=>'NATIVE_BREADCRUMB'
,p_menu_template_id=>4075790987805660140
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(18062404147577832046)
,p_plug_name=>'Team Member Notifications'
,p_static_id=>'team-member-notifications'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2103954283454391425
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ID,',
'       TEAM_MEMBER_ID,',
'       (select first_name||'' ''||last_name',
'          from sp_team_members',
'         where id = n.team_member_id) team_member,',
'       length(EMAIL_CONTENTS) view_email,',
'       case when project_id is not null',
'            then :NOMENCLATURE_PROJECT',
'            when release_id is not null',
'            then ''Release''',
'            when initiative_id is not null',
'            then :NOMENCLATURE_INITIATIVE',
'            when init_focus_area_id is not null',
'            then :NOMENCLATURE_INITIATIVE||'' Focus Area''',
'            when task_id is not null',
'            then ''Milestone/Review/Task''',
'            end notif_about_type,',
'       case when project_id is not null',
'            then (select project',
'                    from sp_projects',
'                   where id = n.project_id)',
'            when release_id is not null',
'            then (select release_train ||release ',
'                    from sp_release_trains',
'                   where id = n.release_id)',
'            when initiative_id is not null',
'            then (select initiative',
'                    from sp_initiatives',
'                   where id = n.initiative_id) ',
'            when init_focus_area_id is not null',
'            then (select i.initiative||'' - ''||fa.focus_area',
'                    from sp_initiatives i,',
'                         sp_initiative_focus_areas fa',
'                   where fa.initiative_id = i.id',
'                     and fa.id = n.init_focus_area_id)',
'            when task_id is not null',
'            then (select (select task_type from sp_task_types rt where rt.id = task_type_id)||',
'                         case when task_sub_type_id is not null then '': '' end ||',
'                         (select task_type from sp_task_types rt where rt.id = task_sub_type_id) ||',
'                         case when task is not null then '' - ''||task end',
'                    from sp_tasks',
'                   where id = n.task_id)',
'            end notif_about,',
'       PROJECT_ID,',
'       task_id,',
'       release_id,',
'       initiative_id,',
'       init_focus_area_id,',
'       NOTIFICATION_PREF,',
'       TITLE,',
