'       listagg(area,'', '' on overflow truncate with count) within group (order by id) details',
'  from SP_AREAS',
' where id in (1,2,3)',
'union all',
'select 2 ob, :NOMENCLATURE_INITIATIVES label, count(*) cnt,',
'       listagg(initiative,'', '' on overflow truncate with count) within group (order by id) details',
'  from SP_INITIATIVES',
' where id in (1,2,3,4,5,6)',
'union all',
'select 8 ob, :NOMENCLATURE_PROJECTS label, count(*) cnt,',
'       listagg(project,'', '' on overflow truncate with count) within group (order by id) details',
'  from SP_PROJECTS',
' where id in (1001,1002,1003,1004,1005,1006,1007,1008,1009,1010,6001,6002,6003,6004,6005,6006,6007,6008,6009,6010,8001,8002,8003,8004,8005,8006,8007,8008,8009,8010,8201,8202,8203,8204,8205,8206,8501,8502,8503,8504,8505,8506,8507,8508,8509,8510,8511,8'
||'512)',
'union all',
'select 4 ob, ''Activities'' label, count(*) cnt,',
'       listagg(comments,'', '' on overflow truncate with count) within group (order by id) details',
'  from sp_activities',
' where id in (1)',
'union all',
'select 5 ob, ''Releases'' label, count(*) cnt,',
'       listagg(release_train||'' '' ||release,'', '' on overflow truncate with count) within group (order by id) details',
'  from sp_release_trains',
' where id in (1,2,3,7,8)',
'union all',
'select 7 ob, :NOMENCLATURE_USERS label, count(*) cnt,',
'       listagg(first_name||'' ''||last_name,'', '' on overflow truncate with count) within group (order by id) details',
'  from SP_TEAM_MEMBERS',
' where id >= 1 and id <= 21',
')',
'where cnt > 0',
'order by ob'))
,p_header=>wwv_flow_string.join(wwv_flow_t_varchar2(
