'   loop'||wwv_flow.LF||
'       remainder := mod(quotient, 10 + 26);'||wwv_flow.LF||
'       quotien';
wwv_flow_imp.g_varchar2_table(341) := 't := floor(quotient  / (10 + 26));'||wwv_flow.LF||
'       if remainder < 26 then'||wwv_flow.LF||
'           digit := chr(ascii(''A'') ';
wwv_flow_imp.g_varchar2_table(342) := '+ remainder);'||wwv_flow.LF||
'       else'||wwv_flow.LF||
'           digit := chr(ascii(''0'') + remainder - 26);'||wwv_flow.LF||
'       end if;'||wwv_flow.LF||
'     ';
wwv_flow_imp.g_varchar2_table(343) := '  ret := digit || ret;'||wwv_flow.LF||
'   end loop ;'||wwv_flow.LF||
'   if length(ret) < 5 then ret := lpad(ret, 4, ''A''); end if ;'||wwv_flow.LF||
' ';
wwv_flow_imp.g_varchar2_table(344) := '  return upper(ret);'||wwv_flow.LF||
'end compress_int;'||wwv_flow.LF||
